# --- Corpus ---------------------------------------------------------------
def load_val_clips():
    print(f"[{now()}] Downloading dataset_e0.h5 from PROJECT_DIR...")
    if not copy_from_project("dataset_e0.h5", LOCAL_H5):
        raise SystemExit("dataset_e0.h5 not found in PROJECT_DIR — run 01_e0_dataextract.py first.")
    ids, wavs = [], []
    with h5py.File(LOCAL_H5, "r") as h5f:
        for gid in ("jamendo", "musdb18"):
            for tid in h5f[gid].keys():
                ids.append(tid)
                wavs.append(h5f[gid][tid][:])
    wavs = np.stack(wavs).astype(np.float32)
    idx = np.arange(len(ids))
    rng = np.random.RandomState(SEED)
    rng.shuffle(idx)
    n_val = int(len(idx) * VAL_FRACTION)
    val_idx = idx[:n_val]
    print(f"[{now()}] {len(val_idx)} held-out clips (identical split to every other experiment).")
    return wavs[val_idx]


# --- Frozen EnCodec + DAC + slim self-test ----------------------------------
def load_models_and_selftest(sample_wav_np):
    print(f"[{now()}] Loading frozen EnCodec (24kHz)...")
    model = EncodecModel.encodec_model_24khz()
    model.set_target_bandwidth(TARGET_BANDWIDTH_KBPS)
    model.eval()
    for p in model.parameters():
        p.requires_grad_(False)
    model = model.to(DEVICE)
    frame_rate = getattr(model, "frame_rate", 75)
    bandwidth = getattr(model, "bandwidth", TARGET_BANDWIDTH_KBPS)

    with torch.no_grad():
        d_total = model.encoder(torch.zeros(1, 1, SR, device=DEVICE)).shape[1]
    d_a_start, d_a_end = 0, d_total // 4
    d_b_start, d_b_end = d_total // 4, 2 * (d_total // 4)
    print(f"[{now()}] D_total={d_total}. Path A [{d_a_start}:{d_a_end}], Path B [{d_b_start}:{d_b_end}].")

    print(f"[{now()}] Loading DAC (24kHz)...")
    import dac
    dac_model_path = dac.utils.download(model_type="24khz")
    dac_model = dac.DAC.load(dac_model_path).to(DEVICE)
    dac_model.eval()

    return model, dac_model, d_total, d_a_start, d_a_end, d_b_start, d_b_end, frame_rate, bandwidth


# --- Trainable modules (identical architecture) ------------------------------
class HyperNet(nn.Module):
    def __init__(self, key_bits, d_channels, hidden=128):
        super().__init__()
        self.d_channels = d_channels
        self.net = nn.Sequential(
            nn.Linear(key_bits, hidden), nn.ReLU(),
            nn.Linear(hidden, hidden), nn.ReLU(),
            nn.Linear(hidden, 2 * d_channels),
        )

    def forward(self, key_bits):
        out = self.net(key_bits)
        gamma_raw, beta_raw = out[:, :self.d_channels], out[:, self.d_channels:]
        gamma = 1.0 + 0.5 * torch.tanh(gamma_raw)
        beta = 0.5 * torch.tanh(beta_raw)
        return gamma, beta


class Extractor(nn.Module):
    def __init__(self, key_bits, channels=32):
        super().__init__()
        def block(cin, cout, stride):
            return nn.Sequential(
                nn.Conv1d(cin, cout, kernel_size=9, stride=stride, padding=4),
                nn.BatchNorm1d(cout), nn.ReLU(),
            )
        self.net = nn.Sequential(
            block(1, channels, 4),
            block(channels, channels * 2, 4),
            block(channels * 2, channels * 4, 4),
            block(channels * 4, channels * 4, 4),
            block(channels * 4, channels * 4, 4),
            nn.AdaptiveAvgPool1d(1),
        )
        self.head = nn.Linear(channels * 4, key_bits)

    def forward(self, wav):
        h = self.net(wav.unsqueeze(1)).squeeze(-1)
        return self.head(h)


def embed_joint(model, wav_1ch, hypernet_a, hypernet_b, key_a, key_b,
                 d_a_start, d_a_end, d_b_start, d_b_end, frame_rate, bandwidth):
    with torch.no_grad():
        raw_emb = model.encoder(wav_1ch)
        gamma_a, beta_a = hypernet_a(key_a)
        gamma_b, beta_b = hypernet_b(key_b)
        gamma_a, beta_a = gamma_a.unsqueeze(-1), beta_a.unsqueeze(-1)
        gamma_b, beta_b = gamma_b.unsqueeze(-1), beta_b.unsqueeze(-1)
        emb_a = raw_emb[:, d_a_start:d_a_end, :] * gamma_a + beta_a
        emb_b = raw_emb[:, d_b_start:d_b_end, :] * gamma_b + beta_b
        emb_mod = torch.cat([emb_a, emb_b, raw_emb[:, d_b_end:, :]], dim=1)
        qres = model.quantizer(emb_mod, frame_rate, bandwidth)
        return model.decoder(qres.quantized)


def match_length(wav_1ch, target_len):
    cur = wav_1ch.shape[-1]
    if cur == target_len:
        return wav_1ch
    if cur > target_len:
        return wav_1ch[..., :target_len]
    return F.pad(wav_1ch, (0, target_len - cur))


# --- Chain step implementations (all take/return [1,1,T] tensors) ----------
def real_mp3_roundtrip_1ch(wav_1ch, bitrate_kbps=128):
    from pydub import AudioSegment
    import soundfile as sf
    wav_np = wav_1ch.squeeze().cpu().numpy()
    with tempfile.NamedTemporaryFile(suffix=".wav") as wav_f, \
         tempfile.NamedTemporaryFile(suffix=".mp3") as mp3_f:
        sf.write(wav_f.name, wav_np, SR)
        AudioSegment.from_wav(wav_f.name).export(mp3_f.name, format="mp3", bitrate=f"{bitrate_kbps}k")
        seg = AudioSegment.from_mp3(mp3_f.name)
        out = np.array(seg.get_array_of_samples()).astype(np.float32)
        if seg.channels > 1:
            out = out.reshape(-1, seg.channels).mean(axis=1)
        out = out / (2 ** (8 * seg.sample_width - 1))
        if seg.frame_rate != SR:
            out = torchaudio.functional.resample(
                torch.from_numpy(out).unsqueeze(0), seg.frame_rate, SR).squeeze(0).numpy()
    out_t = torch.from_numpy(out).float().to(DEVICE).unsqueeze(0).unsqueeze(0)
    return match_length(out_t, wav_1ch.shape[-1])


def resample_roundtrip_1ch(wav_1ch, target_rate=22050):
    down = torchaudio.functional.resample(wav_1ch, SR, target_rate)
    return torchaudio.functional.resample(down, target_rate, SR)


def add_noise_1ch(wav_1ch, snr_db=30):
    sig_power = wav_1ch.pow(2).mean(dim=-1, keepdim=True)
    noise_power = sig_power / (10 ** (snr_db / 10))
    return wav_1ch + torch.randn_like(wav_1ch) * noise_power.sqrt()


def apply_gain_1ch(wav_1ch, g=0.85):
    return wav_1ch * g


def dac_regen_1ch(dac_model, wav_1ch):
    with torch.no_grad():
        x = dac_model.preprocess(wav_1ch, SR)
        z, codes, latents, _, _ = dac_model.encode(x)
        y = dac_model.decode(z)
    return match_length(y, wav_1ch.shape[-1])


# Fixed step pool — moderate, representative settings, not a sweep. Each
# chain below is a specific ordered sequence of these, held constant
# across all 105 clips for direct comparability.
def step_compress(wav_1ch):
    return real_mp3_roundtrip_1ch(wav_1ch, 128)


def step_resample(wav_1ch):
    return resample_roundtrip_1ch(wav_1ch, 22050)


def step_noise(wav_1ch):
    return add_noise_1ch(wav_1ch, 30)


def step_gain(wav_1ch):
    return apply_gain_1ch(wav_1ch, 0.85)


def step_dac(wav_1ch, dac_model):
    return dac_regen_1ch(dac_model, wav_1ch)


CHAINS = {
    "all_benign":   ["compress", "resample", "noise", "gain"],
    "regen_first":  ["dac", "compress", "resample", "noise"],
    "regen_last":   ["compress", "resample", "noise", "dac"],
    "regen_middle": ["compress", "dac", "resample", "noise"],
    "double_regen": ["dac", "compress", "dac", "resample"],
}


def run_step(step_name, wav_1ch, dac_model):
    if step_name == "compress":
        return step_compress(wav_1ch)
    if step_name == "resample":
        return step_resample(wav_1ch)
    if step_name == "noise":
        return step_noise(wav_1ch)
    if step_name == "gain":
        return step_gain(wav_1ch)
    if step_name == "dac":
        return step_dac(wav_1ch, dac_model)
    raise ValueError(f"Unknown step: {step_name}")


# --- Self-test: E3 checkpoint reproduces its own known single-hop behavior -
def selftest_checkpoint(model, hypernet_a, extractor_a, hypernet_b, extractor_b,
                         d_a_start, d_a_end, d_b_start, d_b_end, frame_rate, bandwidth, sample_wav_np):
    print(f"[{now()}] Self-test: E3 checkpoint reproduces known single-hop clean-signal behavior...")
    wav_t = torch.from_numpy(sample_wav_np).float().unsqueeze(0).unsqueeze(0).to(DEVICE)
    key_a = (torch.randint(0, 2, (1, KEY_BITS), device=DEVICE) * 2 - 1).float()
    key_b = (torch.randint(0, 2, (1, KEY_BITS), device=DEVICE) * 2 - 1).float()
    target_a = (key_a > 0).float()
    target_b = (key_b > 0).float()
    x_wm = embed_joint(model, wav_t, hypernet_a, hypernet_b, key_a, key_b,
                        d_a_start, d_a_end, d_b_start, d_b_end, frame_rate, bandwidth)
    with torch.no_grad():
        pred_a = (extractor_a(x_wm.squeeze(1)) > 0).float()
        pred_b = (extractor_b(x_wm.squeeze(1)) > 0).float()
    n_wrong_a = int((pred_a != target_a).sum().item())
    n_wrong_b = int((pred_b != target_b).sum().item())
    print(f"[selftest] clean-signal bits wrong — Path A: {n_wrong_a}/{KEY_BITS}, "
          f"Path B: {n_wrong_b}/{KEY_BITS} (expect close to 0 for both, matching "
          f"E3's own reported ~0.01-0.03 / ~0.09-0.11 benign BER)")
    if n_wrong_a > KEY_BITS // 2 or n_wrong_b > KEY_BITS // 2:
        raise SystemExit("Self-test failed — checkpoint does not reproduce known clean-signal behavior.")
    print(f"[selftest] PASSED.")


# --- Main ---------------------------------------------------------------
def main():
    val_wavs = load_val_clips()
    (model, dac_model, d_total, d_a_start, d_a_end, d_b_start, d_b_end,
     frame_rate, bandwidth) = load_models_and_selftest(val_wavs[0])

    print(f"[{now()}] Downloading e3_joint_checkpoint.pth from PROJECT_DIR (REQUIRED)...")
    if not copy_from_project("e3_joint_checkpoint.pth", LOCAL_E3_CKPT):
        raise SystemExit("e3_joint_checkpoint.pth not found in PROJECT_DIR — run "
                          "05_e3_joint_path.py to completion first.")
    ckpt = torch.load(LOCAL_E3_CKPT, map_location=DEVICE)
    hypernet_a = HyperNet(KEY_BITS, d_a_end - d_a_start).to(DEVICE)
    extractor_a = Extractor(KEY_BITS).to(DEVICE)
    hypernet_b = HyperNet(KEY_BITS, d_b_end - d_b_start).to(DEVICE)
    extractor_b = Extractor(KEY_BITS).to(DEVICE)
    hypernet_a.load_state_dict(ckpt["hypernet_a_state"])
    extractor_a.load_state_dict(ckpt["extractor_a_state"])
    hypernet_b.load_state_dict(ckpt["hypernet_b_state"])
    extractor_b.load_state_dict(ckpt["extractor_b_state"])
    for m in (hypernet_a, extractor_a, hypernet_b, extractor_b):
        m.eval()
    print(f"[{now()}] Loaded E3 checkpoint from epoch {ckpt.get('epoch')}.")

    selftest_checkpoint(model, hypernet_a, extractor_a, hypernet_b, extractor_b,
                         d_a_start, d_a_end, d_b_start, d_b_end, frame_rate, bandwidth, val_wavs[0])

    eval_wavs = val_wavs[:N_EVAL_CLIPS]
    n_hops = 4
    # results[chain_name]["path_a"/"path_b"] = list of n_hops lists, each with n_clips BER contributions
    results = {name: {"path_a": [{"wrong": 0, "total": 0} for _ in range(n_hops)],
                       "path_b": [{"wrong": 0, "total": 0} for _ in range(n_hops)]}
               for name in CHAINS}

    print(f"[{now()}] Running {len(CHAINS)} chains x {n_hops} hops on {len(eval_wavs)} clips...")
    for i in tqdm(range(len(eval_wavs)), desc="chain-of-custody"):
        wav_t = torch.from_numpy(eval_wavs[i]).float().unsqueeze(0).unsqueeze(0).to(DEVICE)
        key_a = (torch.randint(0, 2, (1, KEY_BITS), device=DEVICE) * 2 - 1).float()
        key_b = (torch.randint(0, 2, (1, KEY_BITS), device=DEVICE) * 2 - 1).float()
        target_a = (key_a > 0).float()
        target_b = (key_b > 0).float()

        with torch.no_grad():
            x_wm = embed_joint(model, wav_t, hypernet_a, hypernet_b, key_a, key_b,
                                d_a_start, d_a_end, d_b_start, d_b_end, frame_rate, bandwidth)

        for chain_name, steps in CHAINS.items():
            current = x_wm
            for hop_idx, step_name in enumerate(steps):
                with torch.no_grad():
                    current = run_step(step_name, current, dac_model)
                    current_flat = current.squeeze(1)
                    pred_a = (extractor_a(current_flat) > 0).float()
                    pred_b = (extractor_b(current_flat) > 0).float()
                results[chain_name]["path_a"][hop_idx]["wrong"] += int((pred_a != target_a).sum().item())
                results[chain_name]["path_a"][hop_idx]["total"] += KEY_BITS
                results[chain_name]["path_b"][hop_idx]["wrong"] += int((pred_b != target_b).sum().item())
                results[chain_name]["path_b"][hop_idx]["total"] += KEY_BITS

    ber_results = {}
    for chain_name in CHAINS:
        ber_results[chain_name] = {
            "steps": CHAINS[chain_name],
            "path_a_ber_by_hop": [float(d["wrong"] / d["total"]) for d in results[chain_name]["path_a"]],
            "path_b_ber_by_hop": [float(d["wrong"] / d["total"]) for d in results[chain_name]["path_b"]],
        }

    output = {"chains": ber_results, "n_clips": len(eval_wavs), "key_bits": KEY_BITS,
              "step_settings": {"compress": "MP3@128kbps", "resample": "22050Hz",
                                 "noise": "30dB SNR", "gain": "0.85", "dac": "24kHz full-clip"}}
    with open(LOCAL_RESULTS, "w") as f:
        json.dump(output, f, indent=2)
    copy_to_project(LOCAL_RESULTS, "exp14_chain_of_custody_results.json")

    for chain_name, r in ber_results.items():
        print(f"[{now()}] {chain_name} ({' -> '.join(r['steps'])}):")
        print(f"    Path A BER by hop: {[f'{b:.3f}' for b in r['path_a_ber_by_hop']]}")
        print(f"    Path B BER by hop: {[f'{b:.3f}' for b in r['path_b_ber_by_hop']]}")

    fig, axes = plt.subplots(1, 2, figsize=(14, 5.5))
    hop_x = list(range(1, n_hops + 1))
    colors = plt.cm.tab10(np.linspace(0, 1, len(CHAINS)))
    for (chain_name, r), color in zip(ber_results.items(), colors):
        axes[0].plot(hop_x, r["path_a_ber_by_hop"], "o-", label=chain_name, color=color)
        axes[1].plot(hop_x, r["path_b_ber_by_hop"], "o-", label=chain_name, color=color)
    for ax, title in zip(axes, ["Path A (robust) BER by hop position", "Path B (fragile) BER by hop position"]):
        ax.axhline(0.5, color="gray", linestyle="--", alpha=0.4, label="chance")
        ax.set_xlabel("Hop position in chain")
        ax.set_ylabel("BER")
        ax.set_title(title)
        ax.set_xticks(hop_x)
        ax.legend(fontsize=7)
    fig.suptitle(f"Multi-generation chain-of-custody test — n={len(eval_wavs)} held-out clips, "
                 f"5 chains x 4 hops")
    fig.tight_layout()
    fig.savefig(LOCAL_FIG, dpi=300)
    plt.close(fig)
    copy_to_project(LOCAL_FIG, "fig_14_01_chain_trajectories.png")

    print(f"[{now()}] DONE. exp14_chain_of_custody_results.json, "
          f"fig_14_01_chain_trajectories.png all saved to PROJECT_DIR.")


if __name__ == "__main__":
    main()